const listSupplierInvoices = `-- name: ListSupplierInvoices :many
SELECT i.id, i.uuid, i.invoice_no, i.invoice_date, i.due_date, i.currency, i.description, i.net_amount,
    i.vat_amount, i.total_amount, i.paid_amount, i.status, i.void_reason, i.voided_at, i.created_at, i.updated_at,
    i.attachment_name, i.attachment_content_type, i.attachment_size_bytes,
    (i.attachment_object_key IS NOT NULL)::boolean AS has_attachment,
    (CASE WHEN i.status = 'void' THEN 0 ELSE i.total_amount - i.paid_amount END)::numeric AS open_amount,
    (CASE
        WHEN i.status IN ('paid', 'void') OR i.total_amount <= i.paid_amount THEN 'settled'
        WHEN i.due_date < $1::date THEN 'overdue'
        WHEN i.due_date < $2::date THEN 'due_soon'
        ELSE 'later' END)::text AS due_state,
    s.uuid AS supplier_uuid, s.code AS supplier_code, s.title AS supplier_title,
    a.uuid AS account_uuid, a.code AS account_code,
    cat.uuid AS category_uuid, cat.code AS category_code, cat.name AS category_name,
    b.uuid AS branch_uuid, b.code AS branch_code, b.name AS branch_name,
    v.uuid AS vehicle_uuid, v.plate AS vehicle_plate,
    x.uuid AS expense_uuid,
    u.uuid AS created_by_uuid, u.name AS created_by_name, u.surname AS created_by_surname, u.email AS created_by_email,
    COUNT(*) OVER ()::bigint AS total
FROM supplier_invoices i
JOIN suppliers s ON s.organization_id = i.organization_id AND s.id = i.supplier_id
JOIN accounts a ON a.organization_id = i.organization_id AND a.id = i.account_id
JOIN expense_categories cat ON cat.organization_id = i.organization_id AND cat.id = i.category_id
LEFT JOIN branches b ON b.organization_id = i.organization_id AND b.id = i.branch_id
LEFT JOIN vehicles v ON v.organization_id = i.organization_id AND v.id = i.vehicle_id
LEFT JOIN expenses x ON x.organization_id = i.organization_id AND x.supplier_invoice_id = i.id
LEFT JOIN users u ON u.id = i.created_by
WHERE i.organization_id = $3
  AND ($4::bigint[] IS NULL OR i.branch_id = ANY($4::bigint[]))
  AND ($5::bigint[] IS NULL OR i.id = ANY($5::bigint[]))
  AND ($6::bigint[] IS NULL OR i.supplier_id = ANY($6::bigint[]))
  AND ($7::text[] IS NULL OR i.status = ANY($7::text[]))
  AND ($8::bigint[] IS NULL OR i.category_id = ANY($8::bigint[]))
  AND ($9::bigint[] IS NULL OR i.branch_id = ANY($9::bigint[]))
  AND ($10::date IS NULL OR i.invoice_date >= $10::date)
  AND ($11::date IS NULL OR i.invoice_date <= $11::date)
  AND ($12::date IS NULL OR i.due_date <= $12::date)
  AND ($13::text[] IS NULL OR (CASE
        WHEN i.status IN ('paid', 'void') OR i.total_amount <= i.paid_amount THEN 'settled'
        WHEN i.due_date < $1::date THEN 'overdue'
        WHEN i.due_date < $2::date THEN 'due_soon'
        ELSE 'later' END) = ANY($13::text[]))
  AND (
    $14::text IS NULL
    OR i.invoice_no ILIKE '%' || $14 || '%'
    OR i.description ILIKE '%' || $14 || '%'
    OR s.title ILIKE '%' || $14 || '%'
    OR s.code ILIKE '%' || $14 || '%'
  )
ORDER BY
    CASE WHEN $15::text = 'invoice_date' AND NOT $16::boolean THEN i.invoice_date END ASC,
    CASE WHEN $15::text = 'invoice_date' AND $16::boolean THEN i.invoice_date END DESC,
    CASE WHEN $15::text = 'due_date' AND NOT $16::boolean THEN i.due_date END ASC,
    CASE WHEN $15::text = 'due_date' AND $16::boolean THEN i.due_date END DESC,
    CASE WHEN $15::text = 'total_amount' AND NOT $16::boolean THEN i.total_amount END ASC,
    CASE WHEN $15::text = 'total_amount' AND $16::boolean THEN i.total_amount END DESC,
    CASE WHEN $15::text = 'open_amount' AND NOT $16::boolean THEN i.total_amount - i.paid_amount END ASC,
    CASE WHEN $15::text = 'open_amount' AND $16::boolean THEN i.total_amount - i.paid_amount END DESC,
    CASE WHEN $15::text = 'created_at' AND NOT $16::boolean THEN i.created_at END ASC,
    CASE WHEN $15::text = 'created_at' AND $16::boolean THEN i.created_at END DESC,
    i.id DESC
LIMIT $18 OFFSET $17
`

