func (q *Queries) ListSupplierPayments(ctx context.Context, arg ListSupplierPaymentsParams) ([]ListSupplierPaymentsRow, error) {
	rows, err := q.db.Query(ctx, listSupplierPayments,
		arg.OrganizationID,
		arg.BranchIds,
		arg.Ids,
		arg.SupplierIds,
		arg.CashAccountIds,
		arg.Statuses,
		arg.Methods,
		arg.DateFrom,
		arg.DateTo,
		arg.InvoiceID,
		arg.Q,
		arg.SortField,
		arg.SortDesc,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListSupplierPaymentsRow{}
	for rows.Next() {
		var i ListSupplierPaymentsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Amount,
			&i.Currency,
			&i.PaymentDate,
			&i.Method,
			&i.Reference,
			&i.Description,
			&i.Status,
			&i.VoidReason,
			&i.VoidedAt,
			&i.CreatedAt,
			&i.AllocatedAmount,
			&i.SupplierUuid,
			&i.SupplierCode,
			&i.SupplierTitle,
			&i.AccountUuid,
			&i.AccountCode,
			&i.CashAccountUuid,
			&i.CashAccountCode,
			&i.CashAccountName,
			&i.CashAccountKind,
			&i.BranchUuid,
			&i.BranchCode,
			&i.BranchName,
			&i.LedgerEntryUuid,
			&i.MovementUuid,
			&i.CreatedByUuid,
			&i.CreatedByName,
			&i.CreatedBySurname,
			&i.CreatedByEmail,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

