const payablesSummary = `-- name: PayablesSummary :one
SELECT
    COALESCE(SUM(i.total_amount - i.paid_amount) FILTER (WHERE i.due_date < $1::date), 0)::numeric AS overdue_amount,
    COUNT(*) FILTER (WHERE i.due_date < $1::date)::bigint AS overdue_count,
    COALESCE(SUM(i.total_amount - i.paid_amount)
        FILTER (WHERE i.due_date >= $1::date AND i.due_date < $2::date), 0)::numeric AS due_soon_amount,
    COUNT(*) FILTER (WHERE i.due_date >= $1::date AND i.due_date < $2::date)::bigint AS due_soon_count,
    COALESCE(SUM(i.total_amount - i.paid_amount), 0)::numeric AS open_amount,
    COUNT(*)::bigint AS open_count
FROM supplier_invoices i
WHERE i.organization_id = $3
  AND i.status IN ('open', 'partially_paid')
  AND i.total_amount > i.paid_amount
  AND ($4::bigint[] IS NULL OR i.branch_id = ANY($4::bigint[]))
`

type PayablesSummaryParams struct {
	Today          pgtype.Date `json:"today"`
	Soon           pgtype.Date `json:"soon"`
	OrganizationID int64       `json:"organization_id"`
	BranchIds      []int64     `json:"branch_ids"`
}

type PayablesSummaryRow struct {
	OverdueAmount pgtype.Numeric `json:"overdue_amount"`
	OverdueCount  int64          `json:"overdue_count"`
	DueSoonAmount pgtype.Numeric `json:"due_soon_amount"`
	DueSoonCount  int64          `json:"due_soon_count"`
	OpenAmount    pgtype.Numeric `json:"open_amount"`
	OpenCount     int64          `json:"open_count"`
}

// Open supplier invoices by due state (caller's branch scope).
func (q *Queries) PayablesSummary(ctx context.Context, arg PayablesSummaryParams) (PayablesSummaryRow, error) {
	row := q.db.QueryRow(ctx, payablesSummary,
		arg.Today,
		arg.Soon,
		arg.OrganizationID,
		arg.BranchIds,
	)
	var i PayablesSummaryRow
	err := row.Scan(
		&i.OverdueAmount,
		&i.OverdueCount,
		&i.DueSoonAmount,
		&i.DueSoonCount,
		&i.OpenAmount,
		&i.OpenCount,
	)
	return i, err
}

