const setSupplierInvoicePaid = `-- name: SetSupplierInvoicePaid :execrows
UPDATE supplier_invoices i
SET paid_amount = sub.paid,
    status = (CASE
        WHEN sub.paid >= i.total_amount THEN 'paid'
        WHEN sub.paid > 0 THEN 'partially_paid'
        ELSE 'open' END)
FROM (
    SELECT COALESCE(SUM(al.amount), 0)::numeric AS paid
    FROM supplier_payment_allocations al
    JOIN supplier_payments p ON p.organization_id = al.organization_id AND p.id = al.payment_id
    WHERE al.organization_id = $1
      AND p.organization_id = $1
      AND al.invoice_id = $2
      AND p.status = 'posted'
) sub
WHERE i.organization_id = $1
  AND i.id = $2
  AND i.status <> 'void'
`

type SetSupplierInvoicePaidParams struct {
	OrganizationID int64 `json:"organization_id"`
	ID             int64 `json:"id"`
}

// paid_amount is the sum of the invoice's live allocations; the status
// follows it.
func (q *Queries) SetSupplierInvoicePaid(ctx context.Context, arg SetSupplierInvoicePaidParams) (int64, error) {
	result, err := q.db.Exec(ctx, setSupplierInvoicePaid, arg.OrganizationID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

